INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (66, 'Lubang kancing tidak terbentuk dengan benar', 'Lubang kancing tidak rapi, ukuran tidak sesuai, atau bentuk lubang tidak konsisten.', 'Posisi plaket tidak tepat, parameter proses tidak sesuai, jarum atau pisau pemotong bermasalah, atau material tidak terpasang dengan benar.', 'Periksa posisi plaket, pastikan parameter sesuai produk, periksa kondisi jarum dan mekanisme pemotong, lalu lakukan uji pada satu kemeja sebelum produksi dilanjutkan.', 'Matikan mesin sebelum memeriksa jarum, pisau pemotong, atau bagian mekanisme yang bergerak.', 'Panduan troubleshooting berdasarkan spesifikasi MAICA MA-04');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (66, 'Posisi lubang kancing bergeser dari posisi yang ditentukan', 'Lubang kancing tidak berada pada titik yang seharusnya di plaket kemeja.', 'Posisi plaket tidak tepat, sistem indexing tidak sesuai, atau referensi posisi produk berubah.', 'Periksa posisi pemasangan plaket dan titik referensi indexing, pastikan produk terpasang lurus, lalu lakukan pengaturan posisi sesuai prosedur mesin.', 'Pastikan mesin berhenti sebelum melakukan penyetelan posisi atau mekanisme indexing.', 'Panduan troubleshooting berdasarkan spesifikasi MAICA MA-04');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (66, 'Tekanan udara pneumatik tidak mencukupi', 'Aktuator pneumatik bergerak lambat, tidak penuh, atau proses otomatis berhenti.', 'Tekanan supply kurang dari kebutuhan sekitar 6 bar, terdapat kebocoran, atau regulator dan filter bermasalah.', 'Periksa tekanan udara dan atur sekitar 6 bar, periksa selang serta fitting dari kebocoran, dan periksa kondisi filter serta regulator.', 'Tutup supply udara dan lepaskan tekanan sisa sebelum memperbaiki komponen pneumatik.', 'Panduan troubleshooting berdasarkan spesifikasi MAICA MA-04');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (66, 'Sistem indexing tidak berjalan dengan benar', 'Mesin tidak berpindah ke posisi lubang kancing berikutnya atau urutan proses tidak sesuai.', 'Sensor posisi terganggu, mekanisme indexing kotor, parameter urutan salah, atau aktuator pneumatik tidak bekerja normal.', 'Periksa sensor dan mekanisme indexing, bersihkan area kerja, periksa tekanan udara, dan pastikan urutan program sesuai dengan produk.', 'Jangan memasukkan tangan ke area indexing ketika mesin sedang dalam siklus otomatis.', 'Panduan troubleshooting berdasarkan spesifikasi MAICA MA-04');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (66, 'Pisau atau mekanisme pemotong lubang kancing tidak bekerja dengan baik', 'Lubang tidak terbuka sempurna, hasil potongan kasar, atau proses pemotongan berhenti.', 'Pisau tumpul atau rusak, posisi mekanisme tidak tepat, atau terdapat sisa material pada area pemotongan.', 'Periksa kondisi pisau dan mekanisme pemotong, bersihkan sisa material, dan lakukan penggantian atau penyetelan sesuai prosedur apabila diperlukan.', 'Matikan mesin dan pastikan seluruh gerakan berhenti sebelum menyentuh area pisau atau pemotong.', 'Panduan troubleshooting berdasarkan spesifikasi MAICA MA-04');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (66, 'Mesin berhenti di tengah proses otomatis', 'Siklus pembuatan lubang kancing berhenti sebelum proses selesai.', 'Tekanan udara tidak mencukupi, sensor tidak mendeteksi posisi, terjadi kesalahan mekanisme, atau sistem kontrol menghentikan proses.', 'Periksa indikator atau pesan kesalahan, periksa tekanan udara 6 bar, pastikan sensor dan area kerja tidak terhalang, kemudian jalankan kembali setelah penyebab diperbaiki.', 'Jangan mengabaikan alarm atau interlock keselamatan dan jangan memaksa mekanisme bergerak secara manual saat mesin aktif.', 'Panduan troubleshooting berdasarkan spesifikasi MAICA MA-04');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (66, 'Hasil lubang kancing tidak konsisten antar kemeja', 'Ukuran atau posisi lubang kancing berbeda-beda pada produk yang seharusnya sama.', 'Posisi plaket berubah, indexing tidak konsisten, parameter produk tidak sesuai, atau mekanisme penjepit kurang stabil.', 'Pastikan posisi dan penjepitan plaket konsisten, periksa indexing, periksa parameter produk, dan lakukan pengujian berkala selama produksi.', 'Hentikan mesin sebelum melakukan penyetelan pada penjepit atau mekanisme indexing.', 'Panduan troubleshooting berdasarkan spesifikasi MAICA MA-04');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (66, 'Kapasitas produksi tidak mencapai target', 'Jumlah kemeja yang diproses per jam berada di bawah kapasitas sekitar 120 kemeja/jam.', 'Siklus mesin terlalu lama, sering terjadi penghentian, tekanan udara tidak stabil, atau operator perlu melakukan penyesuaian berulang.', 'Periksa waktu siklus, kurangi penyebab penghentian, pastikan supply udara stabil sekitar 6 bar, dan periksa proses indexing serta posisi produk.', 'Jangan meningkatkan kecepatan atau mengubah parameter di luar batas yang ditentukan tanpa mengikuti prosedur mesin.', 'Panduan troubleshooting berdasarkan spesifikasi MAICA MA-04');
